const finance=(()=>{let f={paidItems:{},adjustments:[],withdrawals:[],commissionPct:10};try{f={...f,...JSON.parse(localStorage.getItem('ekannto_finance_v37')||'{}')}}catch{};const validAdjustment=a=>{const n=Number(a?.amount);return !!a?.sellerId&&Number.isFinite(n)&&Math.abs(n)<=1000000000};let net=0;for(const o of orders)for(let n=0;n<(o.items||[]).length;n++){const i=o.items[n];if(String(i.sellerId)!==String(s.id))continue;const key=`${o.id}::${i.id||i.productId||i.name||n}::${n}`,refunded=/refund/i.test(String(o.status||''))||!!i.refunded;if(f.paidItems?.[key]&&!refunded)net+=(Number(i.price)||0)*(Number(i.qty)||1)*(1-Number(f.commissionPct??10)/100)}const sellerWallet=Number(s.walletBalance);if(Number.isFinite(sellerWallet)){net=sellerWallet}else{for(const a of (f.adjustments||[]))if(validAdjustment(a)&&String(a.sellerId)===String(s.id))net+=(a.type==='add'?1:-1)*Number(a.amount||0)}for(const w of (f.withdrawals||[]))if(String(w.sellerId)===String(s.id)&&['pending','approved','completed','paid'].includes(String(w.status).toLowerCase()))net-=Number(w.amount||0);return Math.max(0,net)})();
